const api=Echo.create({load:()=>JSON.parse(localStorage.getItem('echo-forest-v1')),save:s=>{try{localStorage.setItem('echo-forest-v1',JSON.stringify(s))}catch(e){toast('浏览器未允许保存，当前体验仍可继续')}}});
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='home',filter={mode:'',tag:'',query:''},current='p1',revealed=false,tid='',modal='',draft={mode:'普通',title:'',message:'',story:'',clue:'',tracks:[],tags:['氛围']},meTab='已发布',playing='',queue=[],audio=new Audio(),toastTimer;
const trackOptions=()=>api.tracks.map(t=>`<option value="${t.id}">${t.name}</option>`).join('');
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function run(fn){try{fn()}catch(e){toast(e.message)}}
function go(p){if(p==='home'&&(filter.mode||filter.query||!['','民谣','摇滚','电子'].includes(filter.tag)))filter={mode:'',tag:'',query:''};if(p==='echoes'){meTab='我的回音';p='me'}else if(p==='me'&&meTab==='我的回音'){meTab='已发布'}page=p;modal='';render();window.scrollTo(0,0)}
function openPost(id){current=id;selectedSong=api.post(id).tracks[0];showStory=false;revealed=true;go('detail')}
function pickDiscoveryPost(matches,lastId,rng=Math.random){
 if(!matches.length)return null;
 const ordinary=matches.filter(p=>p.mode!=='故事');
 const stories=matches.filter(p=>p.mode==='故事');
 const chapters=stories.filter(p=>p.chapterStory);
 const groups=[ordinary,chapters.length?chapters:stories].filter(g=>g.length);
 const group=groups[Math.floor(rng()*groups.length)];
 const alternatives=group.filter(p=>p.id!==lastId);
 const pool=alternatives.length?alternatives:group;
 return pool[Math.floor(rng()*pool.length)];
}
function random(){if(catchBusy)return;const conditions=page==='home'?{tag:filter.tag||''}:filter;const picked=pickDiscoveryPost(api.list(conditions),current);if(!picked)return toast('没有匹配的歌单，试试减少筛选条件');if(page==='home'||page==='browse')catchWithWater(picked.id);else openPost(picked.id)}

const poolIcons={
 net:'<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><ellipse cx="27" cy="17" rx="13" ry="10" transform="rotate(-35 27 17)"/><path d="M20 25 7 43c-3 3-7-1-4-4l13-16M16 9c-8 1-13 5-11 9 3 5 20 6 32-2 8-5 10-10 7-12"/></svg>',
 send:'<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="m5 21 37-15-12 36-9-13-16-8Z" fill="currentColor" stroke-linejoin="round"/><path d="M21 29 34 15" stroke="#397862" stroke-width="2"/></svg>',
 echo:'<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="M10 7h27a6 6 0 0 1 6 6v20a6 6 0 0 1-6 6H25l-10 7V39h-5a6 6 0 0 1-6-6V13a6 6 0 0 1 6-6Z"/><circle cx="14" cy="23" r="1"/><circle cx="24" cy="23" r="1"/><circle cx="34" cy="23" r="1"/></svg>',
 user:'<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><circle cx="24" cy="13" r="9"/><path d="M5 45c1-20 37-20 38 0"/></svg>',
 note:'<svg viewBox="0 0 32 32" aria-hidden="true"><path fill="currentColor" d="M12 8v15c-2-1-7 0-7 4 0 5 9 4 9-1V13l10-3v10c-2-1-7 0-7 4 0 5 9 4 9-1V3L12 8Z"/></svg>'};
function home(){const pool=api.list(filter),positions=[[43,53],[63,57.5],[63,71],[50.5,75.4]],bubbles=pool.slice(0,4);return `<main class="pool-screen"><section class="pool-scene" aria-label="曲水相逢，森林音乐池"><div class="pool-shade"></div><div class="pool-name"><i class="sprig left">❧</i><span>曲 水 相 逢</span><i class="sprig right">❧</i></div><section class="pool-glass pool-controls"><div class="pool-heading"><h1>发现音乐池 <span>✦</span></h1><button data-action="go" data-value="browse" aria-label="更多筛选与搜索" title="更多筛选与搜索">⌕</button></div><svg class="pool-leaf" viewBox="0 0 58 120" fill="none" aria-hidden="true"><path d="M45 117C51 64 22 21 20 5" stroke="currentColor"/><path d="M34 54C8 50 6 37 4 28c20 5 29 15 30 26M26 35C15 17 25 11 28 0c7 17 6 29-2 35M38 69C35 42 48 36 53 28c-1 24-6 35-15 41M44 95C20 85 12 69 10 61c23 11 29 19 34 34M45 108C47 83 55 77 58 69c0 22-4 30-13 39" fill="currentColor"/></svg><nav class="pool-genres" aria-label="音乐类型">${['全部','民谣','摇滚','电子'].map((t,i)=>`<button class="${(filter.tag||'全部')===t?'selected':''}" data-action="pool-genre" data-value="${i?t:''}" aria-pressed="${(filter.tag||'全部')===t}">${i?'':'<span class="tiny-play">▷</span>'}${t}</button>`).join('')}</nav></section><div class="fireflies" aria-hidden="true"><i></i><i></i><i></i><i></i></div>${positions.map((position,i)=>`<div class="song-bubble bubble-${i}" style="--x:${position[0]}%;--y:${position[1]}%;--delay:${i*-.7}s" aria-hidden="true"><span class="water-rings"></span><span class="lily-pad"></span><span class="glass-orb">${poolIcons.note}</span></div>`).join('')}${!pool.length?'<div class="pool-empty">这片水面还很安静<br><button data-action="reset-filter">回到全部音乐池 ↗</button></div>':''}<div class="pool-actions"><button class="pool-catch" data-action="random">${poolIcons.net}<span>捞一首</span><i class="button-ripple"></i></button><button class="pool-send pool-glass" data-action="go" data-value="publish">${poolIcons.send}<span>投一首</span></button></div><nav class="pool-bottom pool-glass" aria-label="主导航"><button class="selected" data-action="go" data-value="home" aria-current="page">${poolIcons.net}<span>发现</span></button><button data-action="echoes">${poolIcons.echo}<span>回音</span></button><button data-action="go" data-value="me">${poolIcons.user}<span>我的</span></button></nav></section></main>`}
function smallCard(p,i){return `<button class="small-card" data-action="open" data-value="${p.id}"><div class="cover-art ${p.mode==='故事'?'story':''}"><span class="cover-label">${p.mode==='故事'?'STORY / 一段故事':'MIXTAPE / 一份心情'}</span><span class="art-symbol">${p.mode==='故事'?'☾':'♧'}</span></div><div class="small-card-body"><h3>${esc(p.title)}</h3><p>${api.name(p.owner)} &nbsp; · &nbsp; ${p.tracks.length} 首歌 &nbsp; / &nbsp; ${esc(p.tags[1]||p.tags[0])}</p></div></button>`}
function tracksView(ids,allowLike=false){return ids.map((id,i)=>{const t=api.track(id),liked=api.state.likes.some(l=>l.user===api.user()&&l.post===current&&l.track===id);return `<div class="track"><span class="track-num">${String(i+1).padStart(2,'0')}</span><div class="track-info"><strong>${t.name}</strong><small>${t.artist} · 8 秒片段</small></div>${allowLike?`<button aria-label="标记最喜欢的${t.name}" data-action="like" data-value="${id}">${liked?'♥':'♡'}</button>`:''}<button class="round-play" data-action="play" data-value="${id}" aria-label="播放${t.name}">${playing===id?'Ⅱ':'▶'}</button></div>`}).join('')}
function render(){const kept={};['comment-text','compose-text'].forEach(id=>{const el=document.getElementById(id);if(el)kept[id]=el.value});const scroll=document.querySelector('.screen-scroll');const savedTop=render.lastPage===page&&scroll?scroll.scrollTop:0;document.body.classList.toggle('pool-page',page==='home');$('#app').innerHTML=page==='home'?home():shell(({browse,detail,publish,me,thread,rewards,storyCreate}[page]||browse)());Object.entries(kept).forEach(([id,value])=>{const e=document.getElementById(id);if(e)e.value=value});const area=document.querySelector('.screen-scroll');if(area)area.scrollTop=savedTop;render.lastPage=page}

function play(id,list){if(playing===id&&!list){audio.pause();playing='';queue=[];render();return}queue=list||[];playing=id;audio.src='assets/'+api.track(id).src;audio.play().catch(()=>{playing='';queue=[];render();toast('音频暂时无法播放，请重试')});render()}
audio.onended=()=>{captureDraft();if(queue.length){const next=queue.shift();play(next,queue)}else{playing='';render()}};
document.addEventListener('click',e=>{if(catchBusy)return;const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value;run(()=>{switch(a){case'menu':modal='menu';render();break;case'song-picker':captureDraft();modal='songs';render();break;case'comment-modal':modal='comment';render();break;case'genre':filter.genre=v;if(['民谣','摇滚','电子'].includes(filter.tag))filter.tag='';render();break;case'mood':if(['民谣','摇滚','电子'].includes(filter.tag)){filter.genre=filter.tag;filter.tag=''}filter.tag=filter.tag===v?'':v;render();break;case'echo-tab':echoTab=v;render();break;case'story-toggle':showStory=!showStory;render();break;case'previous-song':stepSong(-1);break;case'next-song':stepSong(1);break;case'shuffle-song':stepSong(1,true);break;case'repeat':repeatOne=!repeatOne;audio.loop=repeatOne;render();break;case'joint-listen':tid=v;go('thread');const joint=api.state.threads.find(t=>t.id===v);audio.loop=false;repeatOne=false;play(joint.cards[0].track,joint.cards.slice(1).map(c=>c.track));break;case'compose-next':const conv=api.state.threads.find(t=>t.id===tid);if(conv.cards.at(-1).user===api.user())throw Error('已经送出这一首，等对方接下一首吧');composeKind='reply';composeThread=tid;replyDraft={track:'t1',text:''};go('publish');break;case'go':if(page==='publish')captureDraft();if(v==='publish')composeKind='';go(v);break;case'intro':go('home');break;case'random':random();break;case'open':openPost(v);break;case'filter':filter.tag=v;render();break;case'pool-genre':filter={mode:'',tag:v,query:''};render();break;case'echoes':go('echoes');break;case'reset-filter':filter={mode:'',tag:'',query:''};render();break;case'reveal':revealed=true;render();break;case'favorite':toast(api.favorite(current)?'已收藏到我的森林':'已取消收藏');render();break;case'gift':api.gift(current);render();toast('送出 1 个音符，谢谢你的心意');break;case'like':api.like(current,v);render();toast('已标记最喜欢的一首');break;case'play':captureDraft();selectedSong=v;play(v);break;case'stop':captureDraft();audio.pause();queue=[];playing='';render();break;case'respond':if(api.post(current).owner===api.user())throw Error('不能给自己回赠');composeKind='first';replyDraft={track:'t1',text:''};go('publish');break;case'close':captureDraft();modal='';render();break;case'draft-mode':captureDraft();draft.mode=v;render();break;case'draft-tag':captureDraft();draft.tags=draft.tags.includes(v)?draft.tags.filter(t=>t!==v):[...draft.tags,v];render();break;case'assist':captureDraft();if(!draft.story.trim())throw Error('先写下真实经历，再整理文案');draft.title=draft.title||draft.story.split(/[。！？\n]/)[0].slice(0,20);draft.clue=draft.story.slice(0,45)+'……';render();toast('已根据原文整理，请检查并修改');break;case'publish-confirm':composeKind='';const p=api.publish(draft);draft={mode:'普通',title:'',message:'',story:'',clue:'',tracks:[],tags:['氛围']};openPost(p.id);toast('已投入本地公共池');break;case'me-tab':meTab=v;render();break;case'claim':api.claim();render();toast('已免费领取 5 个赠送音符');break;case'thread':tid=v;go('thread');break;case'replay':audio.loop=false;repeatOne=false;const t=api.state.threads.find(t=>t.id===tid);play(t.cards[0].track,t.cards.slice(1).map(c=>c.track));break;case'redeem-confirm':modal='redeem:'+v;render();break;case'redeem':api.redeem(v);modal='';render();toast('已生成体验兑换记录');break;}})});
document.addEventListener('change',e=>{if(e.target.name==='tracks'){const id=e.target.value;draft.tracks=e.target.checked?[...new Set([...draft.tracks,id])]:draft.tracks.filter(t=>t!==id)}if(e.target.id==='compose-track'){captureDraft();replyDraft.track=e.target.value;render()}if(e.target.id==='account'){api.switchUser(e.target.value);go('me');toast('已切换本地体验身份')}if(e.target.id==='mode-filter'){filter.mode=e.target.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();run(()=>{switch(e.target.id){case'music-response':replyDraft.text=$('#compose-text').value;replyDraft.track=$('#compose-track').value;if(composeKind==='first'){const sent=api.respond(current,replyDraft.track,replyDraft.text);tid=sent.id;toast('已送进对方的回音箱')}else{api.reply(composeThread,replyDraft.track,replyDraft.text);tid=composeThread;toast('这一首，已接上')}composeKind='';go('thread');break;case'search':filter.query=$('#query').value.trim();render();break;case'comment':api.comment(current,$('#comment-text').value);$('#comment-text').value='';render();toast('听后感受已留下');break;case'publish-form':captureDraft();if(!draft.tracks.length)throw Error('先选至少一首歌');if(draft.mode==='故事'&&(draft.tracks.length<3||draft.tracks.length>5))throw Error('故事歌单需要 3—5 首歌');modal='preview';render();break;case'respond-form':api.respond(current,$('#response-track').value,$('#response-text').value);modal='';render();toast('已送进对方的回音箱');break;case'reply':api.reply(tid,$('#reply-track').value,$('#reply-text').value);$('#reply-text').value='';render();toast('这一首，已接上');break;}})});
let echoTab='待回应',selectedSong='',showStory=false,composeKind='',composeThread='',replyDraft={track:'t1',text:''},repeatOne=false;
function art(id,large=false){const i=api.tracks.findIndex(t=>t.id===id);return `<div class="art art${Math.max(0,i)%4} ${large?'album':''}"><i>☾</i><span>${['林间','晚风','月光','雨后','晴天'][Math.max(0,i)]}</span></div>`}
function songCard(id,options={}){const t=api.track(id);return `<div class="song">${art(id)}<div><strong>${esc(t.name)}</strong><small>原创合成试听 · 00:08</small></div><button class="play-small" data-action="play" data-value="${id}" aria-label="试听${esc(t.name)}">${playing===id?'Ⅱ':'▷'}</button></div>`}
function mobileNav(){const active=page==='thread'||(page==='me'&&meTab==='我的回音')?'echoes':page==='me'||page==='rewards'?'me':'home';return `<nav class="mobile-nav" aria-label="主导航">${[['home','net','发现'],['echoes','echo','回音'],['me','user','我的']].map(([p,i,n])=>`<button class="${p===active?'selected':''}" data-action="go" data-value="${p}"><b>${poolIcons[i]}</b><span>${n}</span></button>`).join('')}</nav>`}
function shell(body){const title={browse:'寻找音乐',detail:'捞到一首',publish:composeKind?'用歌回应':'投一首',me:meTab==='我的回音'?'我的回音':'我的',thread:'我们的接歌',rewards:'奖励中心'}[page]||'曲水相逢';return `<section class="phone route-${page} ${page==='detail'||page==='publish'?'with-action':''}"><header><button class="back-icon" data-action="go" data-value="${page==='thread'?'echoes':page==='publish'&&composeKind?(composeKind==='first'?'detail':'thread'):'home'}" aria-label="返回">‹</button><strong>${title}</strong><button class="more-icon" data-action="menu" aria-label="更多与切换身份">${page==='me'?'<svg class="compact-more" viewBox="0 0 24 24" aria-hidden="true"><circle cx="6" cy="12" r="1.8"/><circle cx="12" cy="12" r="1.8"/><circle cx="18" cy="12" r="1.8"/></svg>':'···'}</button></header><main class="screen-scroll">${body}</main>${page==='detail'?`<div class="bottom-action duo"><button class="secondary" data-action="random">换一首</button><button data-action="respond">用歌回应</button></div>`:''}${page==='publish'?`<div class="bottom-action"><button type="submit" form="${composeKind?'music-response':'publish-form'}">${composeKind?'送出这份回音':'预览发布'}</button></div>`:''}${page==='thread'?`<button class="composer" data-action="compose-next">♫　接下一首，留一句话…<span>➤</span></button>${mobileNav()}`:mobileNav()}${playing&&page!=='detail'?`<button class="floating-audio" data-action="stop">Ⅱ ${esc(api.track(playing).name)} · 停止试听</button>`:''}${modalView()}</section>`}
function browse(){const list=api.list(filter),genre=filter.genre||(['民谣','摇滚','电子'].includes(filter.tag)?filter.tag:''),mood=['民谣','摇滚','电子'].includes(filter.tag)?'':filter.tag;return `<section class="panel filters"><form id="search" class="search"><input id="query" value="${esc(filter.query)}" placeholder="歌曲、歌单，或此刻的心情" aria-label="搜索歌曲或歌单"><button aria-label="搜索">⌕</button></form><div class="chips">${['全部','民谣','摇滚','电子'].map(t=>`<button class="${(genre||'全部')===t?'on':''}" data-action="genre" data-value="${t==='全部'?'':t}">${t}</button>`).join('')}</div><div class="chips mood-chips">${['治愈','独处','快乐','夜晚','学习'].map(t=>`<button class="${mood===t?'on':''}" data-action="mood" data-value="${t}">${t}</button>`).join('')}</div><div class="mode-row"><select id="mode-filter" aria-label="分享模式"><option value="">全部分享</option>${['普通','故事'].map(m=>`<option value="${m}" ${filter.mode===m?'selected':''}>${m}分享</option>`).join('')}</select><button class="link-button" data-action="reset-filter">清空筛选</button></div><p class="hint">让一首歌，恰好遇见你</p></section><section class="result-bubbles" aria-label="匹配的分享">${list.map((p,i)=>`<button class="bubble result-${i%3}" data-action="open" data-value="${p.id}"><span class="avatar">${esc(api.name(p.owner)[0])}</span><strong>${esc(p.title)}</strong><small>${esc(api.name(p.owner))} · ${p.chapterStory?p.chapterStory.chapters.length+' 章 + 结局':p.tracks.length+' 首歌'}</small></button>`).join('')||'<div class="empty panel">这片音乐池暂时没有匹配的分享。<button class="secondary" data-action="reset-filter">减少筛选条件</button></div>'}</section><div class="inline-action"><button data-action="random">从结果中捞一首</button></div>`}
function detail(){const p=api.post(current),id=p.tracks.includes(selectedSong)?selectedSong:p.tracks[0],t=api.track(id),comments=api.state.comments.filter(c=>c.post===current);return `<section class="panel player-panel"><div class="album-wrap">${art(id,true)}</div><h2>${esc(t.name)}</h2><p>原创合成试听</p><input class="seek" type="range" min="0" max="8" step="0.05" value="${playing===id?audio.currentTime||0:0}" aria-label="试听进度" id="seek" ${playing!==id?'disabled':''}><div class="times"><span id="elapsed">${playing===id?formatTime(audio.currentTime):'00:00'}</span><span>00:08</span></div><div class="controls"><button class="icon-button" data-action="shuffle-song" aria-label="随机歌曲">↝</button><button class="icon-button" data-action="previous-song" aria-label="上一首">◁</button><button class="big-play" data-action="play" data-value="${id}" aria-label="${playing===id?'暂停':'播放'}"><svg viewBox="0 0 24 24" aria-hidden="true">${playing===id?'<path d="M8 5v14M16 5v14" stroke-width="2.5"/>':'<path d="M7 4 21 12 7 20Z"/>'}</svg></button><button class="icon-button" data-action="next-song" aria-label="下一首">▷</button><button class="icon-button ${repeatOne?'enabled':''}" data-action="repeat" aria-label="单曲循环" aria-pressed="${repeatOne}">↻</button></div></section><section class="panel note"><div class="by"><span class="avatar">${esc(api.name(p.owner)[0])}</span><div>${esc(api.name(p.owner))}<small>来自${p.tags.find(t=>['民谣','摇滚','电子'].includes(t))||'氛围'}音乐池 · ${p.mode}分享</small></div></div><p>${esc(p.message)}</p>${p.mode==='故事'?`<button class="divider" data-action="story-toggle">${showStory?'收起完整故事':'故事线索 · '+esc(p.clue)}<span>${showStory?'⌃':'⌄'}</span></button>${showStory?`<p class="story-full">${esc(p.story)}</p>`:''}`:`<div class="divider">${esc(p.title)}<span>${p.tracks.length} 首歌</span></div>`}</section><div class="feedback"><button data-action="favorite">${api.isFavorite(current)?'♥ 已收藏':'♡ 收藏'}</button><button data-action="comment-modal">♧ 留言${comments.length?' '+comments.length:''}</button><button data-action="gift">♫ 音符</button><button data-action="like" data-value="${id}" aria-label="标记最喜欢的一首">${api.state.likes.some(l=>l.user===api.user()&&l.post===current&&l.track===id)?'★':'☆'}</button></div>${p.tracks.length>1?`<details class="track-details panel"><summary>这份分享里的其他歌曲 · ${p.tracks.length} 首</summary>${p.tracks.map(t=>songCard(t)).join('')}</details>`:''}`}
function publish(){if(composeKind)return `<form id="music-response" class="panel publish"><p class="hint">${composeKind==='first'?'先将音乐卡片送到对方的回音箱，由对方决定是否继续。':'你一首，我一首，继续这份共同的歌单。'}</p><h3>选择回应的歌曲</h3><select id="compose-track" aria-label="回应歌曲">${api.tracks.map(t=>`<option value="${t.id}" ${t.id===replyDraft.track?'selected':''}>${esc(t.name)}</option>`).join('')}</select>${songCard(replyDraft.track)}<h3>留一句回应</h3><textarea id="compose-text" required maxlength="120" placeholder="你的歌像还在路上，这首像终于回到家。">${esc(replyDraft.text)}</textarea><p class="hint">这一份心意，只送给对方。</p></form>`;return `<form id="publish-form"><section class="panel publish"><div class="chips share-modes">${['普通','故事'].map(m=>`<button type="button" class="${draft.mode===m?'on':''}" data-action="draft-mode" data-value="${m}">${m}分享</button>`).join('')}</div><h3>选择歌曲 <small>${draft.mode==='故事'?'3—5 首':'一首或一组'}</small></h3>${draft.tracks.map(id=>songCard(id)).join('')}<button type="button" class="add" data-action="song-picker">＋ 添加歌曲${draft.tracks.length?' · 已选 '+draft.tracks.length+' 首':''}</button><h3>投向哪个音乐池</h3><select id="draft-pool" aria-label="选择音乐池">${['民谣','摇滚','电子','氛围','轻音乐'].map(t=>`<option ${draft.tags.includes(t)?'selected':''}>${t}</option>`).join('')}</select><h3>添加标签</h3><div class="chips tag-chips">${['治愈','夜晚','独处','散步','放松'].map(t=>`<button type="button" class="${draft.tags.includes(t)?'on':''}" data-action="draft-tag" data-value="${t}">#${t}</button>`).join('')}</div><h3>歌单标题 <small>选填</small></h3><input id="draft-title" maxlength="30" value="${esc(draft.title)}" placeholder="给这份心情取个名字"><h3>想对捞到这首歌的人说…</h3><textarea id="draft-message" maxlength="120" required placeholder="写下此刻的心情、故事或一句话…">${esc(draft.message)}</textarea><p class="hint">不必写成故事，一句话也可以。</p>${draft.mode==='故事'?`<h3>真实经历与歌曲关联</h3><textarea id="draft-story" maxlength="1500" required placeholder="每首歌，让你想起哪个瞬间？">${esc(draft.story)}</textarea><h3>故事线索</h3><input id="draft-clue" maxlength="100" value="${esc(draft.clue)}" placeholder="先留下一点线索"><button type="button" class="add" data-action="assist">整理标题与线索</button><p class="hint">基于原文整理，未接入 AI，不编造经历。</p>`:''}</section></form>`}
function me(){if(meTab==='我的回音')return echoesView();const state=api.state,own=state.posts.filter(p=>p.owner===api.user()),favs=state.posts.filter(p=>api.isFavorite(p.id)),threads=state.threads.filter(t=>t.members.includes(api.user())&&t.status==='active'),feedback=api.feedback(),view=meTab==='收藏'?favs:own;return `<section class="panel profile"><span class="avatar">${esc(api.name(api.user())[0])}</span><h2>${esc(api.name(api.user()))}<button class="inline-icon" data-action="menu" aria-label="切换体验身份">✎</button></h2><p>把歌放进温柔的宇宙里。</p><div class="stats"><div><b>${own.reduce((n,p)=>n+(p.chapterStory?p.chapterStory.chapters.length+1:p.tracks.length),0)}</b><small>已投歌曲</small></div><div><b>${feedback.length+state.threads.filter(t=>t.members.includes(api.user())).length}</b><small>收到回音</small></div><div><b>${threads.length}</b><small>共同歌单</small></div></div></section><div class="tabwrap"><div class="chips">${[['已发布','已投'],['收藏','收藏'],['共同歌单','共同歌单']].map(([id,n])=>`<button class="${meTab===id?'on':''}" data-action="me-tab" data-value="${id}">${n}</button>`).join('')}</div></div>${meTab==='共同歌单'?threads.map(jointCard).join('')||'<div class="panel empty">互相回赠后，共同歌单会留在这里。</div>':`<section class="panel library">${view.map(p=>`<div class="library-item">${p.chapterStory?`<button class="story-library" data-action="open" data-value="${p.id}"><strong>▧ ${esc(p.title)}</strong><small>照片故事 · ${p.chapterStory.chapters.length} 章 + 结局 · ${p.chapterStory.responses.length} 份回音</small></button>`:`${songCard(p.tracks[0])}<button class="library-caption" data-action="open" data-value="${p.id}">${esc(p.title)} · ${p.tracks.length} 首歌</button>`}</div>`).join('')||'<div class="empty">这里还没有歌单。<button class="secondary" data-action="go" data-value="home">去音乐池听听</button></div>'}</section>${threads.slice(0,1).map(jointCard).join('')}`}<div class="wallet-entry"><span>♫ 赠送音符 ${api.wallet().notes}</span><button class="link-button" data-action="go" data-value="rewards">奖励中心 · ${api.wallet().points} 积分</button></div>`}
function jointCard(t){const other=api.name(t.members.find(u=>u!==api.user()));return `<section class="panel joint"><div class="by"><span class="avatar">${esc(other[0])}</span><div><strong>和${esc(other)}的歌单</strong><small>${t.cards.length} 首 · 按交流顺序保存</small></div></div><button class="listen" data-action="joint-listen" data-value="${t.id}">▷ 共同回听</button></section>`}
function echoesView(){const all=api.state.threads.filter(t=>t.members.includes(api.user())),list=all.filter(t=>echoTab==='接歌中'?t.status==='active':t.status==='pending'),feedback=api.feedback();return `<div class="tabwrap"><div class="chips">${['待回应','接歌中','反馈'].map(t=>`<button class="${echoTab===t?'on':''}" data-action="echo-tab" data-value="${t}">${t}</button>`).join('')}</div></div>${echoTab==='反馈'?`<section class="panel feedback-list">${feedback.map(f=>`<div class="feedback-item"><p>${esc(f.text)}</p><small>${esc(api.post(f.post).title)}</small></div>`).join('')||'<div class="empty">下一份回音，也许正在路上。</div>'}</section>`:list.map((t,i)=>{const card=t.cards.at(-1),name=api.name(t.members.find(u=>u!==api.user())),waiting=card.user===api.user();return `<section class="panel ${i?'mini-reply':'reply'}"><div class="by"><span class="avatar">${esc(name[0])}</span><div>${esc(name)}<small>${t.status==='active'?t.cards.length+' 首 · 正在接歌':waiting?'已送出，等待对方回赠':'用歌回应了你'}</small></div>${!waiting?'<i class="dot"></i>':''}</div><p>${esc(card.text)}</p>${songCard(card.track)}<div class="duo"><button class="secondary" data-action="play" data-value="${card.track}">听听看</button><button data-action="thread" data-value="${t.id}">${waiting?'查看回音':t.status==='active'?'接下一首':'回一首'}</button></div></section>`}).join('')||'<div class="panel empty">这里暂时没有回音。<button class="secondary" data-action="go" data-value="home">先捞一首歌</button></div>'}`}
function thread(){const t=api.state.threads.find(t=>t.id===tid),other=api.name(t.members.find(u=>u!==api.user()));return `<section class="panel together"><div><span class="avatar">你</span><span>你</span></div><div class="link">♫<small>${t.status==='active'?'已经交换 '+t.cards.length+' 首歌':'等待双方回赠'}</small></div><div><span class="avatar">${esc(other[0])}</span><span>${esc(other)}</span></div><button class="listen" data-action="replay">▷ 回听我们的接龙</button></section><section class="conversation">${t.cards.map(c=>`<div class="panel message ${c.user===api.user()?'right':'left'}"><small>${c.user===api.user()?'你':esc(api.name(c.user))}</small>${songCard(c.track)}<p>${esc(c.text)}</p></div>`).join('')}</section>${t.cards.at(-1).user===api.user()?'<p class="waiting-note">你的歌已经送出，等待对方接下一首。<br>等待时也可以继续试听。</p>':''}`}
function rewards(){return `<section class="panel reward-wallet"><div><small>赠送音符</small><b>♫ ${api.wallet().notes}</b><button class="link-button" data-action="claim">免费领取今日 5 音符</button></div><div><small>奖励积分</small><b>${api.wallet().points}</b><small>收到有效赠送后累计</small></div></section><p class="page-hint">赠送音符与奖励积分分别记录。兑换仅生成体验记录，不发货。</p>${api.rewards.map(r=>`<section class="panel reward"><h3>${r.icon} ${r.name}</h3><p>${r.cost} 积分 · 库存 ${api.state.stock[r.id]}</p><button class="secondary" data-action="redeem-confirm" data-value="${r.id}" ${!api.state.stock[r.id]||api.wallet().points<r.cost?'disabled':''}>${!api.state.stock[r.id]?'暂时缺货':api.wallet().points<r.cost?'积分不足':'兑换'}</button></section>`).join('')}<section class="panel"><h3>兑换记录</h3>${api.state.redemptions.filter(r=>r.user===api.user()).map(r=>`<p>${esc(r.reward)}<small>${r.date} · ${r.status}</small></p>`).join('')||'<p class="empty">暂无兑换记录</p>'}</section>`}
function modalView(){if(!modal)return '';let body='';if(modal==='menu')body=`<h2>曲水相逢</h2><p class="hint">比赛体验 · 数据保存在本机</p><label for="account">切换体验身份</label><select id="account">${Object.entries(api.people).map(([id,n])=>`<option value="${id}" ${id===api.user()?'selected':''}>${n}</option>`).join('')}</select><button class="secondary" data-action="go" data-value="rewards">奖励中心</button><p class="hint">可切换身份体验双方回赠。示例歌单、接龙和音频仅供体验。</p>`;else if(modal==='songs')body=`<h2>选几首，此刻的歌</h2><p class="hint">${draft.mode==='故事'?'故事分享需要 3—5 首。':'选一首，或选一组都可以。'}</p>${api.tracks.map(t=>`<label class="song-select"><input type="checkbox" name="tracks" value="${t.id}" ${draft.tracks.includes(t.id)?'checked':''}><span>${esc(t.name)}<small>原创合成试听 · 8 秒</small></span><button type="button" class="play-small" data-action="play" data-value="${t.id}" aria-label="试听${esc(t.name)}">▷</button></label>`).join('')}<button data-action="close">选好了</button>`;else if(modal==='comment')body=`<h2>留下你的回音</h2><form id="comment"><textarea id="comment-text" required maxlength="120" placeholder="说一句听后的感受…"></textarea><button>留下留言</button></form>${api.state.comments.filter(c=>c.post===current).map(c=>`<p class="comment-item">${esc(c.text)}<small>${esc(api.name(c.user))}</small></p>`).join('')}`;else if(modal==='preview')body=`<small>发布预览 · ${draft.mode}分享</small><h2>${esc(draft.title||'给路过的你')}</h2><p>${esc(draft.message)}</p>${draft.tracks.map(t=>songCard(t)).join('')}${draft.mode==='故事'?`<p class="hint">先展示的线索</p><p>${esc(draft.clue||'听完这几首歌，再揭晓这段故事。')}</p><p class="story-full">${esc(draft.story)}</p>`:''}<button data-action="publish-confirm">确认内容准确，发布</button>`;else if(modal.startsWith('redeem:')){const r=api.rewards.find(r=>r.id===modal.split(':')[1]);body=`<h2>确认兑换？</h2><p>${r.name}</p><p>将扣除 ${r.cost} 奖励积分，仅生成体验记录。</p><button data-action="redeem" data-value="${r.id}">确认兑换</button>`}return `<div class="modal"><section class="modal-box panel" role="dialog" aria-modal="true" aria-label="${modal==='songs'?'选择歌曲':'操作面板'}"><button class="modal-close" data-action="close" aria-label="关闭">×</button>${body}</section></div>`}
function captureDraft(){if(composeKind){const tx=$('#compose-text');if(tx)replyDraft.text=tx.value;return}if(!$('#publish-form'))return;draft.title=$('#draft-title').value;draft.message=$('#draft-message').value;draft.story=$('#draft-story')?.value||draft.story;draft.clue=$('#draft-clue')?.value||draft.clue;const pool=$('#draft-pool')?.value;if(pool)draft.tags=[...draft.tags.filter(t=>!['民谣','摇滚','电子','氛围','轻音乐'].includes(t)),pool]}
function formatTime(t){return '00:'+String(Math.floor(Number(t)||0)).padStart(2,'0')}

function stepSong(delta,shuffle=false){const ids=api.post(current).tracks;let i=ids.indexOf(selectedSong);if(i<0)i=0;selectedSong=shuffle?ids[Math.floor(Math.random()*ids.length)]:ids[(i+delta+ids.length)%ids.length];play(selectedSong)}
audio.ontimeupdate=()=>{const seek=document.getElementById('seek'),elapsed=document.getElementById('elapsed');if(page==='detail'&&playing===selectedSong){if(seek)seek.value=audio.currentTime;if(elapsed)elapsed.textContent=formatTime(audio.currentTime)}};
document.addEventListener('input',e=>{if(e.target.id==='seek'&&playing===selectedSong){audio.currentTime=Number(e.target.value)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){captureDraft();modal='';render()}});
api.seedShowcase();
// Keep the selected share fixed throughout the short water transition.
let catchBusy=false,catchLayer=null,catchTimer=null,catchExitTimer=null;
function cancelCatchTransition(){clearTimeout(catchTimer);clearTimeout(catchExitTimer);catchTimer=catchExitTimer=null;if(catchLayer)catchLayer.remove();catchLayer=null;catchBusy=false;const app=document.getElementById('app');if(app){app.inert=false;app.removeAttribute('aria-busy');app.classList.remove('catching','catch-arrival')}}
function catchWithWater(id){
 if(catchBusy)return;
 const app=document.getElementById('app');
 const reduced=typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 catchBusy=true;app.inert=true;app.setAttribute('aria-busy','true');app.classList.add('catching');
 audio.pause();playing='';queue=[];
 const layer=document.createElement('div');catchLayer=layer;
 layer.className='catch-overlay'+(page==='home'?' from-pool':' from-search')+(reduced?' reduced':'');
 layer.setAttribute('role','status');layer.setAttribute('aria-live','polite');
 layer.innerHTML=`<div class="catch-backdrop" aria-hidden="true"></div><div class="catch-water"><span class="catch-water-halo" aria-hidden="true"></span>${reduced?'':`<img src="${typeof WATER_TRANSITION_ASSET!=='undefined'?WATER_TRANSITION_ASSET:'assets/water-loading.webp'}" alt="" width="260" height="280">`}<p>听，一份回音正在靠近</p></div>`;
 document.body.appendChild(layer);
 const img=layer.querySelector('img');if(img)img.onerror=()=>{img.hidden=true;layer.classList.add('asset-fallback')};
 const finish=()=>{try{app.classList.remove('catching');openPost(id);app.classList.add('catch-arrival');layer.classList.add('leaving');catchExitTimer=setTimeout(()=>{cancelCatchTransition();const heading=document.querySelector('.phone header strong');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}},reduced?120:480)}catch(e){cancelCatchTransition();toast(e.message||'这份回音暂时没有捞起，再试一次吧')}};
 catchTimer=setTimeout(finish,reduced?120:1600);
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&catchBusy){e.preventDefault();cancelCatchTransition()}});

/* Photo chapters: local competition demo, with explicit author/reader roles. */
const storyChoices=['继续在一起','各自走向新的生活','故事还在继续'];
const storySongNames=['操场上的晴天','靠近一点点','和你散步','下一站的风','仍然选择你'];
function memoryPhoto(i){return 'demo-photo:'+Math.max(0,Math.min(5,i))}
function newChapter(i=0){return {name:'',photo:'',song:'',memory:'',detail:'',photoExample:false}}
function campusStory(){return {title:'毕业那天，我们没有说再见',clue:'四年的照片里，藏着一张没有说完的车票。',mode:'guess',question:'听到这里，你觉得毕业后的我们会怎样？',demo:true,chapters:[['初次相遇','校园活动散场时，我们一起收起了最后一串彩旗。','轻快的节奏，像第一次并肩时忍不住加快的脚步。'],['慢慢靠近','图书馆靠窗的位置，后来总会多留一把椅子。','那些小心翼翼的靠近，都藏在翻书声里。'],['热恋时光','晚饭后绕操场一圈，又一圈，总舍不得回宿舍。','甜甜的旋律，是我们把普通的日子过成纪念日。'],['毕业前夕','车票买好了，我们却一直没有练习说再见。','旋律里有离别，也有一个还没说出口的约定。']].map((c,i)=>({name:c[0],photo:memoryPhoto(i),photoExample:true,song:storySongNames[i],memory:c[1],detail:c[2]})),ending:{name:'仍在一起',photo:memoryPhoto(4),photoExample:true,song:storySongNames[4],memory:'我们经历了异地，也经历了想念。后来，终于又在同一座城市散步。',detail:'这首歌对我们来说，是分别后仍然选择彼此。'},responses:[]}}
let storyAssist=null;
let storyDraft={title:'',clue:'',mode:'guess',question:'听到这里，你觉得后来的我们会怎样？',demo:false,chapters:[newChapter(),newChapter(),newChapter()],ending:newChapter(),responses:[]},storyStep=-1,storyGuess='',storyAuthorView=false,storyPreview=false,storyReplyDraft={song:'',text:''},storyConfirmed=false;
function persistStories(){try{localStorage.setItem('echo-forest-v1',JSON.stringify(api.state));return true}catch(e){toast('本机存储空间不足，本次仍可体验；请导出或减少照片后再保存');return false}}
if(!api.state.posts.some(p=>p.id==='campus-story-v1')){const s=campusStory();api.state.posts.unshift({id:'campus-story-v1',owner:'yu',mode:'故事',title:s.title,message:s.clue,tags:['民谣','治愈','校园'],tracks:['t1','t2','t3','t4','t5'],clue:s.clue,story:'演示内容：照片与音乐的章节故事。',chapterStory:s,created:Date.now()});persistStories()}
function activeStory(){return storyPreview?storyDraft:api.post(current).chapterStory}
const originalOpenPost=openPost;openPost=function(id){storyStep=-1;storyGuess='';storyAuthorView=false;storyPreview=false;storyReplyDraft={song:'',text:''};audio.pause();playing='';queue=[];originalOpenPost(id)};
function sharedNavigation(){const active=page==='thread'||(page==='me'&&meTab==='我的回音')?'echoes':page==='me'||page==='rewards'?'me':'home';return `<nav class="pool-bottom pool-glass unified-nav" aria-label="主导航">${[['home','net','发现'],['echoes','echo','回音'],['me','user','我的']].map(([p,i,n])=>`<button class="${active===p?'selected':''}" data-action="go" data-value="${p}" ${active===p?'aria-current="page"':''}>${poolIcons[i]}<span>${n}</span></button>`).join('')}</nav>`}
mobileNav=sharedNavigation;
const originalHome=home;home=function(){return originalHome().replace(/<nav class="pool-bottom pool-glass"[\s\S]*?<\/nav>/,sharedNavigation()).replace('<div class="fireflies"','<p class="story-home-hint">在这里，遇见一份歌单，或一段故事。</p><div class="fireflies"')};
const originalShell=shell;shell=function(body){let result=originalShell(body);if(page==='detail'&&(storyPreview||api.post(current).chapterStory)){result=result.replace(/<div class="bottom-action duo">[\s\S]*?<\/div>/,'').replace('with-action','chapter-route')};if(page==='storyCreate')result=result.replace('曲水相逢</strong>','创建章节故事</strong>');return result};
const originalDetail=detail;detail=function(){return storyPreview||api.post(current).chapterStory?chapterDetail():originalDetail()};
const originalBrowse=browse;browse=function(){return `<section class="panel story-feature"><small>照片 × 音乐 × 我们</small><h3>毕业那天，我们没有说再见</h3><p>四个章节，一个还未揭晓的后来。</p><button data-story="demo">打开校园故事 · 演示内容 ↗</button></section>`+originalBrowse()};
const originalEchoes=echoesView;echoesView=function(){const own=api.state.posts.filter(p=>p.owner===api.user()&&p.chapterStory&&p.chapterStory.responses.length);return own.map(p=>`<section class="panel story-feature"><small>故事收到新的回音</small><h3>${esc(p.title)}</h3><p>${p.chapterStory.responses.length} 张回应卡片，可保留在故事尾声。</p><button data-story="manage" data-value="${esc(p.id)}">查看回应与尾声</button></section>`).join('')+originalEchoes()};
function storyPhoto(c){const example=/^demo-photo:[0-5]$/.test(c.photo||''),i=example?Number(c.photo.split(':')[1]):0,src=example?(typeof STORY_PHOTOS_ASSET!=='undefined'?STORY_PHOTOS_ASSET:'assets/story-memories.png'):c.photo;return `<figure class="memory-photo"><div class="memory-photo-frame"><img src="${esc(src)}" ${example?`class="photo-atlas" style="left:-${i%2*100}%;top:-${Math.floor(i/2)*100}%"`:''} alt="${esc(c.name||'故事')} · ${c.photoExample?'AI 生成演示照片':'上传的照片'}"></div><figcaption>${c.photoExample?'AI 生成演示照片 · 可替换':'这一刻，留在照片里'}</figcaption></figure>`}
function memorySong(c){return `<div class="memory-song"><span>♫</span><div><strong>${esc(c.song)}</strong><small>歌曲文案示例 / 未接入音源</small></div><span class="no-audio">暂无音源</span></div>`}
function chapterDetail(){const s=activeStory(),n=s.chapters.length,isEnd=storyStep>n,c=storyStep>=0&&storyStep<n?s.chapters[storyStep]:null;return `<div class="story-reader"><div class="story-topline"><span>${s.demo?'演示内容 · 非真实人物经历':'照片与音乐的故事'}</span><button class="link-button" data-story="restart">重新体验 ↺</button></div>${storyPreview?'<div class="preview-banner">发布前预览 <button data-story="edit" class="link-button">返回修改</button></div>':''}<div class="chapter-progress" aria-label="章节进度">${['封面',...s.chapters.map((c,i)=>String(i+1)),s.mode==='memory'?'回忆':'猜测','结局'].map((label,i)=>`<span class="${i===storyStep+1?'current':i<storyStep+1?'done':''}">${label}</span>`).join('')}</div>${storyStep===-1?`<section class="panel memory-cover">${storyPhoto(s.chapters[0])}<small>一段故事 · ${n} 个章节 + 一个结局</small><h1>${esc(s.title)}</h1><p>${esc(s.clue)}</p><button data-story="next">翻开第一张照片 →</button><button class="text-action" data-story="ending">直接看结局</button>${s.demo&&!storyPreview?`<div class="story-mode-switch"><button class="${s.mode==='guess'?'on':''}" data-story="experience-mode" data-value="guess">让朋友猜故事走向</button><button class="${s.mode==='memory'?'on':''}" data-story="experience-mode" data-value="memory">和 TA 一起回忆</button></div>`:''}</section>`:c?`<section class="panel memory-chapter"><small>CHAPTER ${String(storyStep+1).padStart(2,'0')} / ${n}</small><h2>${esc(c.name)}</h2>${storyPhoto(c)}${memorySong(c)}<blockquote>${esc(c.memory)}</blockquote>${c.detail?`<details><summary>照片背后的故事</summary><p>${esc(c.detail)}</p></details>`:''}<div class="duo"><button class="secondary" data-story="prev">上一章</button><button data-story="next">${storyStep===n-1?(s.mode==='memory'?'留下我们的记忆':'猜猜故事走向'):'下一章 →'}</button></div><button class="text-action" data-story="ending">直接看结局</button></section>`:storyStep===n?`<section class="panel guess-panel"><span class="memory-mark">✧</span><small>照片之外，还有一个后来</small><h2>${s.mode==='memory'?'这首歌让你想到我们的哪段回忆？':esc(s.question)}</h2>${s.mode==='memory'?`<p>补充一句记忆，或送来一首歌。</p>${storyResponseForm(true)}<button class="secondary" data-story="ending">看看我们的后来 →</button>`:`<div class="guess-choices">${storyChoices.map((label,i)=>`<button class="${storyGuess===String(i)?'chosen':''}" data-story="guess" data-value="${i}" aria-pressed="${storyGuess===String(i)}"><span>${['01','02','03'][i]}</span>${label}</button>`).join('')}</div><button data-story="reveal" ${storyGuess===''?'disabled':''}>揭晓结局</button><button class="text-action" data-story="ending">直接看结局</button><p class="hint">没有分数，只有你听见的故事。</p>`}</section>`:`<section class="panel memory-ending"><small>THE NEXT CHAPTER · 真实结局${s.demo?'（演示设定）':''}</small><h2>${esc(s.ending.name)}</h2>${storyPhoto(s.ending)}<p class="ending-copy">${esc(s.ending.memory)}</p>${memorySong(s.ending)}<blockquote>${esc(s.ending.detail)}</blockquote>${storyGuess!==''?`<p class="hint">你想象的后来：${storyChoices[Number(storyGuess)]}。谢谢你认真听完我们的故事。</p>`:''}</section><section class="panel story-response"><small>让一首歌，成为故事的回音</small><h3>${s.mode==='memory'?'这首歌让你想到我们的哪段回忆？':'如果让你为这个结局选一首歌，你会选什么？'}</h3>${storyResponseForm(s.mode==='memory')}</section>`}${(isEnd||s.mode==='memory'&&storyStep===n)?storyResponseCards(s):''}${storyPreview?`<section class="panel publish-review"><label><input type="checkbox" id="story-confirm" ${storyConfirmed?'checked':''}>我已核对照片、经历与文案，确认内容准确。</label><button data-story="commit" ${storyConfirmed?'':'disabled'}>确认并发布故事</button></section>`:''}</div>`}
function storyResponseForm(memory){return `<form id="chapter-response"><label>推荐一首歌${memory?'（可选）':''}<select id="story-response-song"><option value="">选择一首示例歌曲</option>${storySongNames.map(t=>`<option ${storyReplyDraft.song===t?'selected':''}>${t}</option>`).join('')}<option value="custom" ${storyReplyDraft.song==='custom'?'selected':''}>自定义歌曲名称</option></select></label><input id="story-response-custom" aria-label="自定义歌曲名称" placeholder="选“自定义歌曲”后，在此填写歌名" maxlength="80" value="${esc(storyReplyDraft.custom||'')}"><label>${memory?'补充一句记忆（可只推荐歌曲）':'一句推荐理由'}<textarea id="story-response-text" maxlength="240" placeholder="这首歌让我想起…">${esc(storyReplyDraft.text)}</textarea></label><button type="submit">${memory?'留下我们的回忆':'送出这首歌'}</button><p class="hint">示例歌曲暂无音源，不模拟播放。</p></form>`}
function storyResponseCards(s){const owner=storyPreview?api.user():api.post(current).owner,canAdd=api.user()===owner||s.demo&&storyAuthorView;return `<section class="panel response-wall"><div class="story-topline"><h3>收到的回音</h3>${s.demo&&!storyPreview?`<button class="link-button" data-story="role">${storyAuthorView?'返回接收者视角':'体验发布者视角'}</button>`:''}</div>${storyAuthorView?'<p class="hint">演示发布者视角 · 可将回应保留为尾声</p>':''}${s.responses.length?s.responses.map(r=>`<article class="memory-response"><small>${esc(api.name(r.user))} · ${r.kind==='memory'?'共同回忆':'用歌回应'}</small>${r.song?`<strong>♫ ${esc(r.song)}</strong><small>暂无音源</small>`:''}<p>${esc(r.text)}</p>${r.added?'<span class="epilogue-label">✓ 已加入故事尾声</span>':canAdd?`<button class="secondary" data-story="epilogue" data-value="${r.id}">加入故事尾声</button>`:'<small>等待发布者决定是否加入尾声</small>'}</article>`).join(''):'<p class="hint">还没有回应，你可以留下第一张音乐卡片。</p>'}</section>${s.responses.some(r=>r.added)?`<section class="panel epilogue"><small>EPILOGUE · 由回音续写</small><h2>故事之后，还有一首歌</h2>${s.responses.filter(r=>r.added).map((r,i)=>`<article><small>补充章节 ${i+1} · ${esc(api.name(r.user))}</small><h3>${r.song?'♫ '+esc(r.song):'一段共同记忆'}</h3><p>${esc(r.text)}</p></article>`).join('')}<p class="hint">原章节与结局歌曲完整保留。</p></section>`:''}`}
function chapterEditor(c,i,ending=false){const key=ending?'ending':String(i);return `<fieldset class="chapter-editor"><legend>${ending?'结局章节（单独设置）':'章节 '+(i+1)}</legend>${!ending?`<div class="edit-order"><button type="button" data-story="move-up" data-value="${i}" ${i===0?'disabled':''}>↑ 前移</button><button type="button" data-story="move-down" data-value="${i}" ${i===storyDraft.chapters.length-1?'disabled':''}>↓ 后移</button><button type="button" data-story="remove" data-value="${i}" ${storyDraft.chapters.length<=3?'disabled':''}>移除</button></div>`:''}<label>${ending?'结局名称':'阶段名称'}<input data-chapter="${key}" data-field="name" value="${esc(c.name)}" maxlength="40" ${ending?'list="ending-labels"':''} placeholder="${ending?'仍在一起 / 各自告别 / 自定义':'例如：初次相遇'}"></label>${c.photo?storyPhoto(c):'<div class="empty-photo">＋ 留下一张这个阶段的照片</div>'}<label class="upload-label">${c.photo?'更换照片':'上传照片'}<input type="file" accept="image/jpeg,image/png,image/webp" data-photo="${key}"></label><button type="button" class="text-action" data-story="sample-photo" data-value="${key}">使用演示照片</button>${chapterSongEditor(c,key)}<label>${ending?'结局文字':'一句回忆'}<textarea data-chapter="${key}" data-field="memory" maxlength="240">${esc(c.memory)}</textarea></label><label>${ending?'为什么这首歌与结局有关':'详细故事（可选）'}<textarea data-chapter="${key}" data-field="detail" maxlength="1000">${esc(c.detail)}</textarea></label></fieldset>`}
function storyCreate(){const d=storyDraft;return `<form id="chapter-create" class="panel chapter-create"><small>1.2 故事歌单 · 把回忆一页页留住</small><h2>照片里的歌</h2><p class="hint">每章依次添加：阶段名称 → 照片 → 一首歌 → 回忆。创建 3—5 章，再留一页给结局。照片仅保存在本机。</p><label>一起怎样读这个故事？<select data-story-field="mode"><option value="guess" ${d.mode==='guess'?'selected':''}>让朋友猜故事走向</option><option value="memory" ${d.mode==='memory'?'selected':''}>和故事里的 TA 一起回忆</option></select></label><button type="button" class="add" data-story="load-example">填入校园演示故事</button><label>故事标题<input data-story-field="title" value="${esc(d.title)}" maxlength="60"></label><label>主题线索<input data-story-field="clue" value="${esc(d.clue)}" maxlength="160"></label>${d.mode==='guess'?`<label>猜测问题<input data-story-field="question" value="${esc(d.question)}" maxlength="120"></label>`:'<p class="hint">共同回忆提问：这首歌让你想到我们的哪段回忆？</p>'}<datalist id="story-songs">${storySongNames.map(n=>`<option value="${n}">`).join('')}</datalist><datalist id="ending-labels"><option value="仍在一起"><option value="各自告别"><option value="故事还在继续"></datalist>${d.chapters.map((c,i)=>chapterEditor(c,i)).join('')}<button type="button" class="add" data-story="add" ${d.chapters.length>=5?'disabled':''}>＋ 添加章节 · ${d.chapters.length} / 5</button>${chapterEditor(d.ending,0,true)}<section class="assist-box"><h3>AI 文案辅助 · 本地演示</h3><p class="hint">尚未接入 AI。演示仅摘取你写下的回忆生成标题和线索，保留当前顺序；可手动调序、编辑，不补写经历。</p><button type="button" class="secondary" data-story="organize">根据已填内容整理</button>${storyAssist?`<div class="assist-suggestion"><small>待确认建议 · 仅摘取原文</small><p>标题：${esc(storyAssist.title)}</p><p>线索：${esc(storyAssist.clue)}</p><p>提问：${esc(storyAssist.question)}</p><p>章节顺序：${storyDraft.chapters.map((c,i)=>esc(c.name||"章节 "+(i+1))).join(" → ")}</p><small>顺序沿用你的输入，可用各章的前移 / 后移调整。</small><button type="button" data-story="use-assist">采用建议，再编辑</button></div>`:""}</section><button type="submit">预览章节与结局 →</button></form>`}
function validateStory(s){if(s.chapters.length<3||s.chapters.length>5)throw Error('请设置 3—5 个故事章节');if(!s.title.trim()||!s.clue.trim())throw Error('请填写故事标题和主题线索');if(s.mode==='guess'&&!s.question.trim())throw Error('请填写猜测问题');for(const [i,c] of [...s.chapters,s.ending].entries()){if(!c.name.trim()||!c.photo||!c.song.trim()||!c.memory.trim())throw Error((i===s.chapters.length?'结局章节':'第 '+(i+1)+' 章')+'还缺少名称、照片、歌曲或回忆')}if(!s.ending.detail.trim())throw Error('请说明结局歌曲与经历的关联')}
function storyNavigate(step){audio.pause();playing='';queue=[];storyStep=step;render();const el=document.querySelector('.screen-scroll');if(el)el.scrollTop=0;const ending=document.querySelector('.memory-ending');if(ending&&step===activeStory().chapters.length+1)ending.classList.add('ending-reveal')}
function storyAct(action,value){const s=(page==='detail'&&(storyPreview||api.post(current).chapterStory))?activeStory():null;switch(action){case'demo':openPost('campus-story-v1');break;case'manage':openPost(value);storyNavigate(activeStory().chapters.length+1);break;case'next':storyNavigate(storyStep+1);break;case'prev':storyNavigate(storyStep-1);break;case'guess':storyGuess=value;render();break;case'reveal':if(storyGuess==='')return toast('选一个你想象的走向，或直接看结局');storyNavigate(s.chapters.length+1);break;case'ending':storyNavigate(s.chapters.length+1);break;case'restart':storyGuess='';storyAuthorView=false;storyReplyDraft={song:'',text:''};storyNavigate(-1);break;case'experience-mode':s.mode=value;storyGuess='';render();break;case'role':storyAuthorView=!storyAuthorView;render();break;case'epilogue':if(!(s.demo&&storyAuthorView)&&!storyPreview&&api.post(current).owner!==api.user())throw Error('由发布者决定是否加入尾声');const r=s.responses.find(r=>r.id===value);if(r&&!r.added){r.added=true;if(!storyPreview)persistStories();render();toast('已作为补充章节保留，原有歌曲未替换')}break;case'create':audio.pause();playing='';queue=[];storyPreview=false;go('storyCreate');break;case'edit':storyPreview=false;go('storyCreate');break;case'load-example':storyDraft=campusStory();storyAssist=null;storyConfirmed=false;render();toast('已填入演示内容，可替换照片与文案');break;case'add':if(storyDraft.chapters.length<5)storyDraft.chapters.push(newChapter());render();break;case'remove':if(storyDraft.chapters.length>3)storyDraft.chapters.splice(Number(value),1);render();break;case'move-up':case'move-down':const i=Number(value),j=i+(action==='move-up'?-1:1);if(j>=0&&j<storyDraft.chapters.length)[storyDraft.chapters[i],storyDraft.chapters[j]]=[storyDraft.chapters[j],storyDraft.chapters[i]];render();break;case'sample-photo':const c=value==='ending'?storyDraft.ending:storyDraft.chapters[Number(value)];c.photo=memoryPhoto(value==='ending'?4:Number(value));c.photoExample=true;render();break;case'organize':const first=storyDraft.chapters.find(c=>c.memory.trim());if(!first)throw Error('先写下一句真实回忆');storyAssist={title:first.memory.trim().slice(0,32),clue:storyDraft.chapters.filter(c=>c.name.trim()).map(c=>c.name.trim()).join(' · ').slice(0,160),question:'听到这里，你觉得后来的我们会怎样？'};render();toast('整理建议已生成，请核对后采用');break;case'use-assist':if(storyAssist){storyDraft.title=storyAssist.title;storyDraft.clue=storyAssist.clue;storyDraft.question=storyAssist.question;storyConfirmed=false;storyAssist=null;render();toast('已采用建议，所有文案仍可编辑')}break;case'commit':if(!storyConfirmed)throw Error('请先确认内容准确');validateStory(storyDraft);const saved=JSON.parse(JSON.stringify(storyDraft));saved.responses=[];const id='chapter-'+Date.now();api.state.posts.unshift({id,owner:api.user(),mode:'故事',title:saved.title,message:saved.clue,tags:['民谣','治愈','故事'],tracks:['t1'],story:'照片章节故事',clue:saved.clue,chapterStory:saved,created:Date.now()});const persisted=persistStories();storyPreview=false;openPost(id);if(persisted)toast('已发布到本机音乐池');break}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-story]');const mode=e.target.closest('[data-action="draft-mode"]');if(mode&&mode.dataset.value==='故事'){e.preventDefault();e.stopImmediatePropagation();captureDraft();storyAct('create');return}if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(!catchBusy)run(()=>storyAct(b.dataset.story,b.dataset.value))},true);
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.storyField){storyDraft[t.dataset.storyField]=t.value;storyConfirmed=false}if(t.dataset.chapter){const c=t.dataset.chapter==='ending'?storyDraft.ending:storyDraft.chapters[Number(t.dataset.chapter)];c[t.dataset.field]=t.value;storyConfirmed=false}if(t.id==='story-response-song')storyReplyDraft.song=t.value;if(t.id==='story-response-custom')storyReplyDraft.custom=t.value;if(t.id==='story-response-text')storyReplyDraft.text=t.value});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='story-confirm'){storyConfirmed=t.checked;render()}if(t.dataset.storyField==='mode'){storyDraft.mode=t.value;render()}if(t.dataset.photo!==undefined&&t.files&&t.files[0]){const file=t.files[0],c=t.dataset.photo==='ending'?storyDraft.ending:storyDraft.chapters[Number(t.dataset.photo)];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024)return toast('请选择 15 MB 以内的 JPG、PNG 或 WebP 照片');const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,900/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);c.photo=canvas.toDataURL('image/jpeg',.72);c.photoExample=false;storyConfirmed=false;render();toast('照片已放入这一章')};image.onerror=()=>toast('照片无法读取，请换一张');image.src=reader.result};reader.onerror=()=>toast('照片读取失败');reader.readAsDataURL(file)}});
document.addEventListener('submit',e=>{if(!['chapter-create','chapter-response'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();run(()=>{if(e.target.id==='chapter-create'){validateStory(storyDraft);storyPreview=true;storyConfirmed=false;storyStep=-1;storyGuess='';go('detail')}else{const s=activeStory(),memory=s.mode==='memory',choice=$('#story-response-song').value,song=choice==='custom'?$('#story-response-custom').value.trim():choice,text=$('#story-response-text').value.trim();if(memory?!song&&!text:!song||!text)throw Error(memory?'补充一句记忆，或推荐一首歌':'请选择歌曲，并写一句推荐理由');s.responses.push({id:'response-'+Date.now()+'-'+s.responses.length,user:api.user(),song,text,kind:memory?'memory':'song',added:false});const saved=storyPreview||persistStories();storyReplyDraft={song:'',text:'',custom:''};render();toast(saved?'回音已送达，发布者可以将它加入尾声':'回应已加入本次体验，但未能保存到本机')}})},true);


let chapterSongPicker='';
function chapterSongEditor(c,key){return `<section class="chapter-song-slot"><h3>♫ 这一章的歌曲 <small>必填 · 1 首</small></h3>${c.song?memorySong(c):'<p class="hint">给这张照片选一首歌，让旋律记住这一刻。</p>'}${chapterSongPicker===key?`<div class="chapter-song-picker"><label>从示例中选择<select id="chapter-song-example"><option value="">选择一首示例歌曲</option>${storySongNames.map((n,i)=>`<option value="${esc(n)}">${esc(n)} · ${['轻快','暧昧','甜蜜','离别','坚定陪伴'][i]}</option>`).join('')}</select></label><p class="hint">也可以直接填写你想用的歌曲。</p><label>歌名<input id="chapter-song-name" maxlength="80" value="${esc(c.song)}" placeholder="例如：与你有关的那首歌"></label><label>歌手（选填）<input id="chapter-song-artist" maxlength="40" placeholder="填写歌手名字"></label><div class="duo"><button type="button" class="secondary" data-chapter-song="cancel">取消</button><button type="button" data-chapter-song="confirm" data-value="${key}">加入这一章</button></div></div>`:`<button type="button" class="add chapter-add-song" data-chapter-song="open" data-value="${key}">${c.song?'更换歌曲':'＋ 添加歌曲'}</button>`}<p class="hint">当前演示保存歌曲信息，尚未接入音乐平台音源。</p></section>`}
document.addEventListener('change',e=>{if(e.target.id==='chapter-song-example'&&e.target.value){document.getElementById('chapter-song-name').value=e.target.value;document.getElementById('chapter-song-artist').value=''}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-chapter-song]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();run(()=>{const a=b.dataset.chapterSong,key=b.dataset.value;if(a==='open'){chapterSongPicker=key;render()}else if(a==='cancel'){chapterSongPicker='';render()}else if(a==='confirm'){const name=document.getElementById('chapter-song-name').value.trim(),artist=document.getElementById('chapter-song-artist').value.trim();if(!name)throw Error('先选择一首示例歌曲，或填写歌名');const c=key==='ending'?storyDraft.ending:storyDraft.chapters[Number(key)];c.song=name+(artist?' · '+artist:'');storyConfirmed=false;chapterSongPicker='';render();toast('歌曲已加入这一章')}})},true);

render();